/**
 * GitHub Node - Version 1.1
 * Discriminator: resource=file, operation=get
 */


interface Credentials {
  githubApi: CredentialReference;
  githubOAuth2Api: CredentialReference;
  githubAppApi: CredentialReference;
}

/** Get the data of a single pull request */
export type GithubV11FileGetParams = {
  resource: 'file';
  operation: 'get';
  authentication?: 'accessToken' | 'oAuth2' | 'githubAppApi' | Expression<string>;
/**
 * Repository Owner
 * @searchListMethod getUsers
 * @default {"mode":"list","value":""}
 */
    owner?: { __rl: true; mode: 'list' | 'url' | 'name'; value: string; cachedResultName?: string };
/**
 * Repository Name
 * @searchListMethod getRepositories
 * @default {"mode":"list","value":""}
 */
    repository?: { __rl: true; mode: 'list' | 'url' | 'name'; value: string; cachedResultName?: string };
/**
 * The file path of the file. Has to contain the full path.
 */
    filePath: string | Expression<string>;
/**
 * Whether to set the data of the file as binary property instead of returning the raw API response
 * @default true
 */
    asBinaryProperty?: boolean | Expression<boolean>;
/**
 * Put Output File in Field
 * @hint The name of the output binary field to put the file in
 * @displayOptions.show { asBinaryProperty: [true] }
 * @default data
 */
    binaryPropertyName?: string | Expression<string>;
/**
 * Additional fields to add
 * @default {}
 */
    additionalParameters?: {
    /** The name of the commit/branch/tag. Default: the repository’s default branch (usually master).
     */
    reference?: string | Expression<string>;
  };
};

export type GithubV11FileGetOutput = {
  _links?: {
    git?: string;
    html?: string;
    self?: string;
  };
  content?: string;
  download_url?: string;
  encoding?: string;
  git_url?: string;
  html_url?: string;
  name?: string;
  path?: string;
  sha?: string;
  size?: number;
  type?: string;
  url?: string;
};

export type GithubV11FileGetNode = {
  type: 'n8n-nodes-base.github';
  version: 1.1;
  config: NodeConfig<GithubV11FileGetParams> & { credentials?: Credentials };
  output?: Items<GithubV11FileGetOutput>;
};